waves.point_eqs_eel:
w = min(1, 8 * min(sample, 1 - sample));
ang = sample * 6.2831853 + q2 * 0.5 + value2 * 0.7 * w;
rad = q8 + value1 * 1.1 * w;
x = 0.5 + rad * cos(ang);
y = 0.5 + rad * sin(ang);

frame_eqs_eel:
kick = max(bass - bass_att, 0);
pulse = max(pulse * 0.86, min(kick * 0.9, 1));
q3 = pulse;
pop = max(pop * 0.78, min(max(bass - 1.2, 0) * 0.55, 1.4));
q5 = pop;
dd = (0.0015 + 0.002 * min(bass_att, 2) + 0.006 * q3) * 60 / max(fps, 1);
dive = dive + dd;
dturn = 0.002 + 0.003 * (mid_att - 1) + 0.01 * q3;
turn = turn + dturn;
morph = morph + 0.004 + 0.01 * min(mid_att, 2) + 0.02 * pop;
q1 = dive;
q2 = turn;
q4 = morph;
q6 = pow(10, dd);
q7 = dturn + 2.2 * dd;
cool = max(cool - 1 / max(fps, 1), 0);
stamp = above(kick, 0.2) * below(cool, 0.001);
cool = if(stamp, 0.16, cool);
q8 = 0.2 + 0.06 * min(kick / 0.5, 1);
q9 = stamp;

warp:
shader_body {
 vec2 s = texsize.xy / min(texsize.x, texsize.y);
 vec2 p = (uv_orig - 0.5) * s;
 float acc = 0.0;
 float hue = 0.0;
 float wsum = 0.0;
 {
   float f = fract(q1 + 0.0 / 3.0);
   float w = sin(3.14159265 * f);
   float sc = 1.3 / pow(10.0, f);
   float an = q2 + f * 2.2 + 0.0;
   vec2 z = vec2(p.x * cos(an) - p.y * sin(an), p.x * sin(an) + p.y * cos(an)) * sc + vec2(0.18, 0.11);
   vec2 kc = vec2(-0.58, -0.54) + 0.06 * vec2(cos(q4 + 0.0), sin(q4 * 0.8 + 0.0));
   float sum = 0.0;
   float orb = 0.0;
   float prev = length(z);
   for (int i = 0; i < 14; i++) {
     z = abs(z) / max(dot(z, z), 0.0001) + kc;
     float l = length(z);
     sum += abs(l - prev);
     prev = l;
     orb += exp(-l * l * 1.5);
   }
   float v = pow(clamp((sum / 14.0 - 0.8) / 2.5, 0.0, 1.0), 1.3);
   acc += v * w;
   hue += clamp(v * 0.6 + 0.4 * fract(orb * 0.25 + 0.0 * 0.13), 0.0, 1.0) * w;
   wsum += w;
 }
 {
   float f = fract(q1 + 1.0 / 3.0);
   float w = sin(3.14159265 * f);
   float sc = 1.3 / pow(10.0, f);
   float an = q2 + f * 2.2 + 2.1;
   vec2 z = vec2(p.x * cos(an) - p.y * sin(an), p.x * sin(an) + p.y * cos(an)) * sc + vec2(0.18, 0.11);
   vec2 kc = vec2(-0.58, -0.54) + 0.06 * vec2(cos(q4 + 1.7), sin(q4 * 0.8 + 2.3));
   float sum = 0.0;
   float orb = 0.0;
   float prev = length(z);
   for (int i = 0; i < 14; i++) {
     z = abs(z) / max(dot(z, z), 0.0001) + kc;
     float l = length(z);
     sum += abs(l - prev);
     prev = l;
     orb += exp(-l * l * 1.5);
   }
   float v = pow(clamp((sum / 14.0 - 0.8) / 2.5, 0.0, 1.0), 1.3);
   acc += v * w;
   hue += clamp(v * 0.6 + 0.4 * fract(orb * 0.25 + 1.0 * 0.13), 0.0, 1.0) * w;
   wsum += w;
 }
 {
   float f = fract(q1 + 2.0 / 3.0);
   float w = sin(3.14159265 * f);
   float sc = 1.3 / pow(10.0, f);
   float an = q2 + f * 2.2 + 4.2;
   vec2 z = vec2(p.x * cos(an) - p.y * sin(an), p.x * sin(an) + p.y * cos(an)) * sc + vec2(0.18, 0.11);
   vec2 kc = vec2(-0.58, -0.54) + 0.06 * vec2(cos(q4 + 3.4), sin(q4 * 0.8 + 4.6));
   float sum = 0.0;
   float orb = 0.0;
   float prev = length(z);
   for (int i = 0; i < 14; i++) {
     z = abs(z) / max(dot(z, z), 0.0001) + kc;
     float l = length(z);
     sum += abs(l - prev);
     prev = l;
     orb += exp(-l * l * 1.5);
   }
   float v = pow(clamp((sum / 14.0 - 0.8) / 2.5, 0.0, 1.0), 1.3);
   acc += v * w;
   hue += clamp(v * 0.6 + 0.4 * fract(orb * 0.25 + 2.0 * 0.13), 0.0, 1.0) * w;
   wsum += w;
 }
 acc /= wsum;
 hue /= wsum;
 vec2 cs = (uv - 0.5) * s;
 vec2 c1 = vec2(cs.x * cos(q7) - cs.y * sin(q7), cs.x * sin(q7) + cs.y * cos(q7)) / q6;
 vec2 c1u = c1 / s + 0.5;
 vec3 fb = texture(sampler_main, c1u).xyz;
 float ink = fb.z * 0.996 / sqrt(q6) * step(2.5, frame);
 float b = max(acc, fb.x * (0.72 + 0.12 * q3));
 float h = mix(hue, fb.y, step(acc, fb.x * 0.9) * 0.8);
 ret = vec3(clamp(b, 0.0, 1.0), h, clamp(ink, 0.0, 1.0));
}

comp:
shader_body {
 vec2 s = texsize.xy / min(texsize.x, texsize.y);
 vec2 p = (uv - 0.5) * s;
 vec2 px = texsize.zw * 1.5;
 vec3 bl = GetBlur1(uv - vec2(px.x, 0.0));
 vec3 br = GetBlur1(uv + vec2(px.x, 0.0));
 vec3 bd = GetBlur1(uv - vec2(0.0, px.y));
 vec3 bu = GetBlur1(uv + vec2(0.0, px.y));
 float hx = (br.x - bl.x) + (br.z - bl.z) * 0.6;
 float hy = (bu.x - bd.x) + (bu.z - bd.z) * 0.6;
 vec3 n = normalize(vec3(-hx * 3.0, -hy * 3.0, 1.0));
 vec3 L = normalize(vec3(-0.5, 0.6, 0.8));
 float diff = max(dot(n, L), 0.0);
 float spc = pow(max(dot(reflect(-L, n), vec3(0.0, 0.0, 1.0)), 0.0), 30.0);
 vec3 m = texture(sampler_main, uv).xyz;
 float ink = m.z;
 float body_x = clamp(m.y, 0.0, 1.0) * 5.0;
 vec3 body = mix(NOKKVI_RAMP0, NOKKVI_RAMP1, clamp(body_x, 0.0, 1.0));
 body = mix(body, NOKKVI_RAMP2, clamp(body_x - 1.0, 0.0, 1.0));
 body = mix(body, NOKKVI_RAMP3, clamp(body_x - 2.0, 0.0, 1.0));
 body = mix(body, NOKKVI_RAMP4, clamp(body_x - 3.0, 0.0, 1.0));
 body = mix(body, NOKKVI_RAMP5, clamp(body_x - 4.0, 0.0, 1.0));
 vec3 col = mix(NOKKVI_BG, body, smoothstep(0.08, 0.55, m.x));
 col = mix(col, NOKKVI_TEXT, smoothstep(0.85, 1.0, m.x) * 0.5);
 col *= 0.55 + 0.6 * diff;
 float inkc_x = clamp(0.3 + 0.7 * ink, 0.0, 1.0) * 5.0;
 vec3 inkc = mix(NOKKVI_RAMP0, NOKKVI_RAMP1, clamp(inkc_x, 0.0, 1.0));
 inkc = mix(inkc, NOKKVI_RAMP2, clamp(inkc_x - 1.0, 0.0, 1.0));
 inkc = mix(inkc, NOKKVI_RAMP3, clamp(inkc_x - 2.0, 0.0, 1.0));
 inkc = mix(inkc, NOKKVI_RAMP4, clamp(inkc_x - 3.0, 0.0, 1.0));
 inkc = mix(inkc, NOKKVI_RAMP5, clamp(inkc_x - 4.0, 0.0, 1.0));
 inkc = mix(inkc, NOKKVI_TEXT, smoothstep(0.55, 1.0, ink) * 0.85);
 col = mix(col, inkc * (0.7 + 0.6 * diff), clamp(ink * 1.3, 0.0, 1.0) * 0.85);
 vec3 b2 = GetBlur2(uv);
 col += NOKKVI_HIGHLIGHT * b2.x * (0.04 + 0.25 * q3);
 col += NOKKVI_HIGHLIGHT * b2.z * (0.35 + 0.4 * q3);
 col += NOKKVI_TEXT * spc * max(m.x, ink) * (0.3 + 0.5 * q5);
 col += NOKKVI_WARM * smoothstep(0.8, 1.0, m.x) * clamp(treb_att - 0.9, 0.0, 1.0) * 0.3;
 col *= 0.8 + 0.2 * smoothstep(1.1, 0.2, length(p));
 col *= 1.0 + 0.3 * q5;
 ret = col;
}
